  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (94::BIGINT, 'No sé por que tiene comentarios malos, explica bien y sus evaluaciones son super claras y sencillas. Hay otros profes que dan el curso más de programar y en compus, pero ella tampoco es que lo haga dificil.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2026-10-10T00:00:00+00:00'::TIMESTAMPTZ, '2884ad2b723ee5801b678818845803202c8c324b343f54f5240f7527142c9878'::TEXT, ARRAY[968]::BIGINT[]),
    (94::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo']::TEXT[], '2026-06-08T00:00:00+00:00'::TIMESTAMPTZ, '1e27f9d4cbcbddc4f4437661f793d200dbc55f880c88a79982ae6b631ddbc014'::TEXT, ARRAY[2806, 2746, 2807, 2741, 2805, 2766, 2756, 2803]::BIGINT[]),
    (94::BIGINT, 'No la recomiendo para nada, hace que el curso sea DEMASIADO pesado, deja consignas muy largas que realmente quitan mucho tiempo, porque ni siquiera sirven para estudiar, ya que los exámenes los hace totalmente diferentes y en la clase los ejercicios los hace por encima.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2022-06-21T00:00:00+00:00'::TIMESTAMPTZ, '097879e3c8b04d19b344b8f12d6a7e2bddfefcf82e1db095a35fd0a3582f5128'::TEXT, ARRAY[968]::BIGINT[]),
    (94::BIGINT, 'Excelente profesora, siempre dispuesta a ayudar, las clases fueron asincrónicas en su mayoría.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación']::TEXT[], '2021-07-18T00:00:00+00:00'::TIMESTAMPTZ, '93eabc8b0ea34e84602c4ef8fcf0fe32da4afd3c44d3baabb578a507bbab9adb'::TEXT, ARRAY[968]::BIGINT[]),
    (94::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Muchos exámenes']::TEXT[], '2021-07-13T00:00:00+00:00'::TIMESTAMPTZ, '544adc311ec85b16624da69b5e033b21f4c0718f191e9ebcc6ca866ca425e9a7'::TEXT, ARRAY[2439]::BIGINT[]),
    (94::BIGINT, 'La profesora es muy buena explicando, siempre está dispuesta ayudar al estudiante. No obstante se recomienda la constante práctica y realización de los ejercicios de las consignas, así como asistir a las horas de consultas para evacuar dudas en los trabajos de programación.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Muchos exámenes', 'Brinda apoyo']::TEXT[], '2021-07-12T00:00:00+00:00'::TIMESTAMPTZ, 'ae0d27ae273c839e766aca404e2fc73c9e8c65f23d2b777400adbe29f8104c80'::TEXT, ARRAY[968]::BIGINT[]),
    (94::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Muchos exámenes', 'Tomaría su clase nuevamente']::TEXT[], '2021-05-31T00:00:00+00:00'::TIMESTAMPTZ, 'bc9ea5b8f72a61f8cb5ed9492ca7f4398b0b0e83db0a4b45adaf9cca49944994'::TEXT, ARRAY[935]::BIGINT[]),
    (94::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Exámenes retadores', 'Tomaría su clase nuevamente']::TEXT[], '2020-12-17T00:00:00+00:00'::TIMESTAMPTZ, 'be4ce3ea0f9b39fa4a76e930a165f2acd144347c3e0aa977d717081e8a1215fb'::TEXT, ARRAY[935]::BIGINT[]),
    (94::BIGINT, 'Es muy buena profe, todo queda claro y si no, mantiene contacto con los estudiantes para aclarar dudas. En modalidad virtual deja consignas semanales que llevan bastante trabajo pero es lo necesario para abarcar los temas del curso. Hay que programar bastante en matlab'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-24T00:00:00+00:00'::TIMESTAMPTZ, 'e20c1adc0a2daa0930f71c6097c622e675ce89688a2bde3c4e6c8ec569ec7ab9'::TEXT, ARRAY[968]::BIGINT[]),
    (94::BIGINT, 'En modalidad presencial no era tan pesada, pero en modalidad virtual envía consignas que pueden fácilmente ocupar dos a tres días para realizarse, ademas que sus clases en modalidad virtual son poco claras y sus retro-alimentaciones vía correo son igual de confusas, con semestre liviano es viable.'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas']::TEXT[], '2020-07-28T00:00:00+00:00'::TIMESTAMPTZ, 'f2defd1ff6cddfc9058494949a641b439daf40a751e9339a8e3ec048af36e48d'::TEXT, ARRAY[968]::BIGINT[]),
    (94::BIGINT, 'Complica mucho el curso, en la clase se entiende poco, las tareas son duras y califica duro. No la recomiendo si no les gusta programar ni estar buscando a la profe en consulta para pedirle ayuda.'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-02-04T00:00:00+00:00'::TIMESTAMPTZ, '9dfe3f7e589664dbdf6a2c8e59b89d33d6ec05f860d2f15c41001c6ba73e1313'::TEXT, ARRAY[968]::BIGINT[]),
    (94::BIGINT, 'Es de las mejores profes para dar ese curso. Explica demasiado bien la materia. Ayuda mucho en consulta y no califica tan duro. Lo que jode un poco son las tareas programadas que tiene el curso pero ella en clases realiza las partes más complicadas de la tarea.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-13T00:00:00+00:00'::TIMESTAMPTZ, '595cb6bd0639c97cbe1ed54c0d1c36cd655acec2b0527a60e7d9aa3a0d02ab85'::TEXT, ARRAY[968]::BIGINT[]),
    (94::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-04-18T00:00:00+00:00'::TIMESTAMPTZ, '9eab3424a83384eef4f38960458b3f0281f464144b433acaac95279226cad535'::TEXT, ARRAY[968]::BIGINT[]),
    (94::BIGINT, 'Explica bien y es buena gente. Ayuda demasiado en consulta. La clase es algo aburrida. Las tareas programadas son muy largas y a veces dificles así que busquen un buen grupo. Si califica algo duro pero no para tanto. Es pasable.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-30T00:00:00+00:00'::TIMESTAMPTZ, '5f76107e8e4be6059d7eaaefbf3534cb21179074a8067c5adfe6a1846d2088d7'::TEXT, ARRAY[968]::BIGINT[]),
    (94::BIGINT, 'Sus clases son muy buenas y se explica claramente. Las tareas individuales son puntos fáciles. No sean como yo y traigan amigos porque hay muchos trabajos grupales muy largos.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2017-06-18T00:00:00+00:00'::TIMESTAMPTZ, '3f3fcbdc8073e3d733858a96af7c748081255c2ba52bfd2f3cb046c8320b6833'::TEXT, ARRAY[968]::BIGINT[]),
    (94::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2016-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'd5a7ea8da446c4deded575c1b32464f51f7a13d61dc1542fb4e0bff670903f61'::TEXT, ARRAY[605]::BIGINT[]),
    (94::BIGINT, 'Esta profe es demasiado ruda, califica duro y deja laboratorios en matlab demasiado largos y rudos.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2016-02-10T00:00:00+00:00'::TIMESTAMPTZ, '0d44d8fb14d6f5571f28497037e976eb6587788f98a2b28eeaaa2d303dc8119c'::TEXT, ARRAY[968]::BIGINT[]),
    (94::BIGINT, 'Excelente profesora, califica duro, pero es justificable, la recomiendo'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-03T00:00:00+00:00'::TIMESTAMPTZ, '3df0ff616cb87fd30fca764ee5a08bf8951d5daecd64af9eac2122229679be71'::TEXT, ARRAY[1034]::BIGINT[]),
    (94::BIGINT, 'Explica muy rápido, los laboratorios son, al principio, difíciles. Pero por otro lado, en consulta explica hasta que a usted le quede claro, y deja quices para la casa, lo cual ayuda mucho. Califica justo'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-10-27T00:00:00+00:00'::TIMESTAMPTZ, '6d5a7eea75c1df28bffc00b8595b5933af89486d6f25149574ea1dbd9667e915'::TEXT, ARRAY[968]::BIGINT[]),
    (94::BIGINT, 'La verdad la profe explica pero muy rápido y sus clases son un bostezo los quices son duros, tampoco es imposible pasarle'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-30T00:00:00+00:00'::TIMESTAMPTZ, '56552993c534ab7d33eff9ab86364fe609a1b69fabc93497ff23f77e5679a7f6'::TEXT, ARRAY[563]::BIGINT[]),
    (94::BIGINT, 'En general es buena profe, lo quices si son rudos pero generalmente se tiene una idea de que va a tratar por que ella dice y para el examen uno siempre esta preparado con lo que vio. En consulta siempre aclara cualquier duda.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-28T00:00:00+00:00'::TIMESTAMPTZ, 'e8f67d817e8c2bb6f0919dddb14d1a4a4d2de817ff61ac5fb49fb24520819a51'::TEXT, ARRAY[3061]::BIGINT[]),
    (94::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-23T00:00:00+00:00'::TIMESTAMPTZ, 'e27ddd375f7230ba14f5d657b78baa028b9ea71f17b529782a6951bebcb8fdc5'::TEXT, ARRAY[968]::BIGINT[]),
    (94::BIGINT, 'Excelente profesora, explica sumamente bien y es muy agradable, pero a como explica, califica rudo'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-17T00:00:00+00:00'::TIMESTAMPTZ, '3df97ca8e8c05f62bb752adffdd4f1846851ced16310917b343a36415e38c92d'::TEXT, ARRAY[1641, 1642]::BIGINT[]),
    (94::BIGINT, 'Califica muy fuerte'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'd14dc1e4689554a695c6831b7122b5ba5298d1b7c7e1f2fe4df99e970e05088b'::TEXT, ARRAY[1670, 1669]::BIGINT[]),
    (94::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'e21ec1dcc27bdf7e5729c69186f04f423936988555c2330df148b5eeccc39739'::TEXT, ARRAY[1641, 1642]::BIGINT[]),
    (94::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'd02b7c50d60341d4e44355878984035218c031a7920db3ad83dacce755d90d4a'::TEXT, ARRAY[968]::BIGINT[]),
    (94::BIGINT, 'Muy buena profe, da un poco rápido las clases pero explica todas las veces que sea necesario..'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-14T00:00:00+00:00'::TIMESTAMPTZ, '92b02f26b8ce3fea920351657671572ccf93d9066c1b23ef555a0af4ab5f43a0'::TEXT, ARRAY[1034]::BIGINT[]),
    (94::BIGINT, 'Explica bien pero hay que llevar el hilo de las cosas porque uno se pierde fácil y califica duro.'::TEXT, 2.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-14T00:00:00+00:00'::TIMESTAMPTZ, 'b849430ee5694c4e1dfc654200e12090e8049f0c084a076917f21a2c8ec55aa6'::TEXT, ARRAY[563, 564]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
